def quitar_accesorios(apps, schema_editor):
    Equipo = apps.get_model('proyectos', 'Equipo')
    SesionEnsayo = apps.get_model('proyectos', 'SesionEnsayo')
    for codigo, _, _ in ACCESORIOS:
        equipo = Equipo.objects.filter(codigo=codigo).first()
        if equipo and not SesionEnsayo.objects.filter(
            models.Q(anillos=equipo) | models.Q(neopreno=equipo)
        ).exists():
            equipo.delete()
